            { method: 'notifyActionCardStateChange', params: ['card-1', 'ready'] },
        ])
        requests.forEach(({ id, method }) => {
            const result = method === 'beginActionPromptDraft'
                ? 2
                : method === 'setActionQueuedMessage'
                    ? { accepted: true }
                    : method === 'sendActionQueuedMessage'
